#!/usr/bin/env python3
"""
autodl-rutorrent compatibility patch for modern ruTorrent:

- XHTML-style self-closing tags on non-void elements (<div .../>, <select .../>,
  <tbody .../>) break dialog DOM creation in HTML5 parsers.
- UploadMethod.js still calls the old _getdir constructor shape.
- getConf.php still calls the removed global isLocalMode() helper instead of
  User::isLocalMode().
- autodl-rutorrent loads css/<theme>.min.css, where <theme> is the active
  ruTorrent theme's directory name in lower case, and ships stylesheets only
  for the six themes it knew about. With any other theme the request returns
  404, the filter list gets no height or scrollbar, and on ruTorrent 5 the
  Filters window grows past the bottom of the screen with a long filter list.
  The themes in THEME_STYLESHEETS get a generated stylesheet that keeps the
  window on screen.
- autodl's own six stylesheets give the Filters window a fixed 350px height,
  so on ruTorrent 5 the filter settings spill out below it. The same layout
  is appended to each of them between LAYOUT_BEGIN and LAYOUT_END, with
  DIALOG_POSITION for blue.min.css, which took autodl's dialog windows out of
  ruTorrent's absolute positioning.

The image runs this at build time and 03-config.sh runs it on every start, so
a persisted custom autodl-rutorrent plugin is patched too.
"""
from __future__ import annotations

import pathlib
import re
import sys

# Theme (lower-case directory name) -> bundled autodl stylesheet whose colours
# suit it. None: the theme styles autodl's colours itself, so the generated
# file holds only the layout. club-QuickBox is the original club-QuickBox
# (and the directory name a customer's own v2 install uses);
# club-QuickBox-v2 is the bundled v2.
THEME_STYLESHEETS = {
    "club-quickbox": None,
    "club-quickbox-v2": None,
    "darkbetter": "dark",
    "materialdesign": "dark",
    "oblivionblue": "oblivion",
}

GENERATED_MARKER = "/* Generated by Appbox patch-autodl-rutorrent-html5.py; rewritten on every start. */"

# Keep the Filters window on screen in ruTorrent 5. The filter list and the
# filter settings scroll inside the window, and OK and Cancel stay at the
# bottom. club-QuickBox sets #autodl-filters-left to min-height:max-content
# and lays #autodl-filters-right out as a flex row, hence the !important rules
# and the button alignment.
FILTERS_LAYOUT = """\
#autodl-filters{height:auto}
#autodl-filters-left{min-height:0 !important;padding-bottom:0 !important}
#autodl-filters-list{height:auto !important;max-height:min(420px, calc(100vh - 220px)) !important;overflow-y:auto !important}
#autodl-filters-contents{max-height:calc(100vh - 180px);overflow-y:auto}
#autodl-filters-right>.dialog-buttons{align-self:flex-end !important;align-items:center !important}
"""

SOURCE_MAP_RE = re.compile(r"/\*# sourceMappingURL=[^*]*\*/\s*")

# Stylesheets autodl-rutorrent ships itself. Their colours are kept; the
# layout is appended between these markers and replaced on every run.
BUNDLED_STYLESHEETS = ("acid", "blue", "dark", "excel", "oblivion", "standard")
LAYOUT_BEGIN = "/* Appbox Filters layout (patch-autodl-rutorrent-html5.py): begin */"
LAYOUT_END = "/* Appbox Filters layout: end */"
# blue.min.css sets #autodl-filters, #autodl-trackers, #autodl-servers,
# #autodl-prefs and #autodl-multiselect to position:relative, which also
# matches the dialog windows with those ids and overrides ruTorrent's
# .dlg-window{position:absolute}: the dialog then sits below the page and the
# browser scrolls the page to reach it. Put the windows back; the inner
# content divs that share the ids stay relative.
DIALOG_POSITION = (
    ".dlg-window#autodl-filters,.dlg-window#autodl-trackers,.dlg-window#autodl-servers,"
    ".dlg-window#autodl-prefs,.dlg-window#autodl-multiselect{position:absolute}"
)


def without_layout(content: str) -> str:
    """content with an appended Appbox layout block removed."""
    start = content.find(LAYOUT_BEGIN)
    if start == -1:
        return content
    end = content.find(LAYOUT_END, start)
    if end == -1:
        return content[:start].rstrip("\n") + "\n"
    return (content[:start] + content[end + len(LAYOUT_END):].lstrip("\n")).rstrip("\n") + "\n"


def append_layout(css_dir: pathlib.Path) -> None:
    if not css_dir.is_dir():
        return
    block = f"{LAYOUT_BEGIN}\n{FILTERS_LAYOUT.strip()}\n{DIALOG_POSITION}\n{LAYOUT_END}\n"
    for name in BUNDLED_STYLESHEETS:
        path = css_dir / f"{name}.min.css"
        if not path.is_file():
            continue
        content = path.read_text(encoding="utf-8")
        fixed = without_layout(content).rstrip("\n") + "\n" + block
        if fixed != content:
            path.write_text(fixed, encoding="utf-8")


def write_theme_stylesheets(css_dir: pathlib.Path) -> None:
    if not css_dir.is_dir():
        return
    for theme, colours in THEME_STYLESHEETS.items():
        target = css_dir / f"{theme}.min.css"
        if target.exists() and not target.read_text(encoding="utf-8").startswith(GENERATED_MARKER):
            # Not ours, for example a custom plugin that ships its own.
            continue
        parts = [GENERATED_MARKER]
        if colours is not None:
            source = css_dir / f"{colours}.min.css"
            if source.is_file():
                parts.append(SOURCE_MAP_RE.sub("", without_layout(source.read_text(encoding="utf-8"))).strip())
        parts.append(FILTERS_LAYOUT.strip())
        content = "\n".join(parts) + "\n"
        if not target.exists() or target.read_text(encoding="utf-8") != content:
            target.write_text(content, encoding="utf-8")


def main() -> None:
    base = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else "/var/www/rutorrent/plugins/autodl-rutorrent")
    js = base / "js"
    tag_re = re.compile(r"<(div|select|tbody)([^>]*)/>")
    for path in js.glob("*.js"):
        content = path.read_text(encoding="utf-8")
        fixed = tag_re.sub(lambda m: f"<{m.group(1)}{m.group(2)}></{m.group(1)}>", content)
        if path.name == "UploadMethod.js":
            fixed = fixed.replace(
                'this.getdirButton1 = new theWebUI.rDirBrowser(idDlg, this.id("watchdir-folder"), this.id("getdir-button"));',
                'this.getdirButton1 = new theWebUI.rDirBrowser(this.id("watchdir-folder"));',
            )
            fixed = fixed.replace(
                'this.getdirButton2 = new theWebUI.rDirBrowser(idDlg, this.id("rtorrent-folder"), this.id("rt-getdir-button"));',
                'this.getdirButton2 = new theWebUI.rDirBrowser(this.id("rtorrent-folder"));',
            )
        if fixed != content:
            path.write_text(fixed, encoding="utf-8")

    get_conf = base / "getConf.php"
    if get_conf.exists():
        content = get_conf.read_text(encoding="utf-8")
        fixed = content.replace("if (!isLocalMode()) {", "if (!User::isLocalMode()) {")
        if fixed != content:
            get_conf.write_text(fixed, encoding="utf-8")

    append_layout(base / "css")
    write_theme_stylesheets(base / "css")


if __name__ == "__main__":
    main()
